  LinearLayout top=new LinearLayout(this);top.setGravity(Gravity.CENTER_VERTICAL);top.setPadding(dp(3),dp(3),dp(3),0);
  EVIconView logo=new EVIconView(this,EVIconView.Type.LIGHTNING);logo.setDark(dark);top.addView(logo,new LinearLayout.LayoutParams(dp(42),dp(42)));
  LinearLayout titles=new LinearLayout(this);titles.setOrientation(LinearLayout.VERTICAL);titles.setPadding(dp(9),0,0,0);TextView title=tv("EV Charge Calculator",22,text());title.setTypeface(null,1);titles.addView(title);TextView subline=tv("ENERGÍA · CARGA · MOVILIDAD ELÉCTRICA",9,blue);subline.setTypeface(null,1);subline.setLetterSpacing(.08f);titles.addView(subline);top.addView(titles,new LinearLayout.LayoutParams(0,-2,1));
  themeButton=tv(dark?"☀":"☾",21,text());themeButton.setGravity(Gravity.CENTER);themeButton.setBackground(bg(dark?Color.rgb(15,34,53):Color.WHITE,15,1));themeButton.setContentDescription("Cambiar tema");themeButton.setOnClickListener(v->toggleTheme());top.addView(themeButton,new LinearLayout.LayoutParams(dp(46),dp(46)));root.addView(top);space(14);
  LinearLayout hero=new LinearLayout(this);hero.setGravity(Gravity.CENTER_VERTICAL);hero.setPadding(dp(16),dp(12),dp(16),dp(12));hero.setBackground(bg(dark?Color.argb(210,7,32,53):Color.argb(235,232,246,255),20,1));EVIconView car=new EVIconView(this,EVIconView.Type.CAR);car.setDark(dark);hero.addView(car,new LinearLayout.LayoutParams(dp(52),dp(52)));LinearLayout ht=new LinearLayout(this);ht.setOrientation(LinearLayout.VERTICAL);ht.setPadding(dp(12),0,0,0);TextView a=tv("Tu carga, de un vistazo",16,text());a.setTypeface(null,1);ht.addView(a);ht.addView(tv("Calcula energía, coste y hora de inicio.",12,sub()));hero.addView(ht,new LinearLayout.LayoutParams(0,-2,1));root.addView(hero);space(14);
  LinearLayout c1=card();sectionTitle(c1,"Batería",EVIconView.Type.BATTERY);battery=edit("80,0");row(c1,"Capacidad",battery,"kWh");batS=seek(300,160);c1.addView(batS,new LinearLayout.LayoutParams(-1,dp(38)));rangeSummary=tv("",14,text());rangeSummary.setGravity(Gravity.CENTER);rangeSummary.setTypeface(null,1);c1.addView(rangeSummary);range=new BatteryRangeView(this);c1.addView(range,new LinearLayout.LayoutParams(-1,dp(62)));chargeAmount=tv("",13,sub());chargeAmount.setGravity(Gravity.CENTER);c1.addView(chargeAmount);root.addView(c1);space(12);
  LinearLayout c2=card();sectionTitle(c2,"Carga",EVIconView.Type.CHARGER);power=edit("3,45");row(c2,"Potencia",power,"kW");spaceIn(c2,8);price=edit("0,15");row(c2,"Precio energía",price,"€/kWh");spaceIn(c2,9);
  LinearLayout xr=new LinearLayout(this);xr.setGravity(Gravity.CENTER_VERTICAL);LinearLayout xl=new LinearLayout(this);xl.setOrientation(LinearLayout.VERTICAL);TextView xt=tv("Centinela / XGuard",14,text());xt.setTypeface(null,1);xl.addView(xt);xl.addView(tv("Consumo adicional cada 24 h",11,sub()));xr.addView(xl,new LinearLayout.LayoutParams(0,54,1));xSwitch=new Switch(this);xSwitch.setChecked(true);xr.addView(xSwitch,new LinearLayout.LayoutParams(dp(50),54));xguard=edit("5,0");xr.addView(xguard,new LinearLayout.LayoutParams(dp(78),54));TextView xp=tv("%",13,sub());xp.setGravity(Gravity.CENTER);xr.addView(xp,new LinearLayout.LayoutParams(dp(36),54));c2.addView(xr);root.addView(c2);space(12);
