 void applyTheme(){background.setDark(dark);getWindow().setStatusBarColor(dark?Color.rgb(4,10,19):Color.rgb(242,248,253));getWindow().setNavigationBarColor(dark?Color.rgb(4,10,19):Color.rgb(242,248,253));getWindow().getDecorView().setSystemUiVisibility(dark?0:View.SYSTEM_UI_FLAG_LIGHT_STATUS_BAR);themeButton.setText(dark?"☀":"☾");themeButton.setTextColor(text());}
 void toggleTheme(){dark=!dark;rebuildTheme();}
 void rebuildTheme(){String b=battery.getText().toString(),pw=power.getText().toString(),pr=price.getText().toString(),dep=departure.getText().toString(),xg=xguard.getText().toString();int rc=range.getCurrent(),rt=range.getTarget();boolean xs=xSwitch.isChecked();build();battery.setText(b);power.setText(pw);price.setText(pr);departure.setText(dep);xguard.setText(xg);range.setValues(rc,rt);xSwitch.setChecked(xs);xguard.setEnabled(xs);applyTheme();calculate();}
 void ensureVisibleAboveKeyboard(View v){if(scroll==null||v==null)return;v.requestRectangleOnScreen(new Rect(0,0,v.getWidth(),v.getHeight()),true);int[] loc=new int[2],sloc=new int[2];v.getLocationOnScreen(loc);scroll.getLocationOnScreen(sloc);int bottom=loc[1]+v.getHeight(),visibleBottom=sloc[1]+scroll.getHeight(),delta=bottom-(visibleBottom-dp(24));if(delta>0)scroll.smoothScrollBy(0,delta);}
 void hideKeyboard(View v){((InputMethodManager)getSystemService(INPUT_METHOD_SERVICE)).hideSoftInputFromWindow(v.getWindowToken(),0);}
 void pickTime(EditText e){String[] a=e.getText().toString().split(":");int h=7,m=0;try{h=Integer.parseInt(a[0]);m=Integer.parseInt(a[1]);}catch(Exception ignored){}new TimePickerDialog(this,(v,hh,mm)->{setText(e,String.format(Locale.US,"%02d:%02d",hh,mm));calculate();},h,m,true).show();}
 void setup(){batS.setOnSeekBarChangeListener(slider(v->setText(battery,fmt(v/2.0,1))));range.setListener((c,t)->calculate());battery.addTextChangedListener(watch(this::syncBat));power.addTextChangedListener(watch(this::calculate));price.addTextChangedListener(watch(this::calculate));xguard.addTextChangedListener(watch(this::calculate));departure.addTextChangedListener(watch(this::calculate));xSwitch.setOnCheckedChangeListener((b,c)->{xguard.setEnabled(c);calculate();});}
 SeekBar.OnSeekBarChangeListener slider(java.util.function.IntConsumer f){return new SeekBar.OnSeekBarChangeListener(){public void onProgressChanged(SeekBar s,int p,boolean from){if(from&&!busy){busy=true;f.accept(p);busy=false;calculate();}}public void onStartTrackingTouch(SeekBar s){}public void onStopTrackingTouch(SeekBar s){}};}
 android.text.TextWatcher watch(Runnable r){return new android.text.TextWatcher(){public void beforeTextChanged(CharSequence s,int a,int c,int d){}public void onTextChanged(CharSequence s,int a,int b,int c){if(!busy)r.run();}public void afterTextChanged(android.text.Editable e){}};}
 void setText(EditText e,String s){e.setText(s);e.setSelection(e.length());}
 void syncBat(){if(busy)return;double v=num(battery);if(v>=0&&v<=150){busy=true;batS.setProgress((int)Math.round(v*2));busy=false;}calculate();}
 double num(EditText e){try{return Double.parseDouble(e.getText().toString().replace(',','.'));}catch(Exception x){return 0;}}
 String fmt(double v,int d){DecimalFormat f=new DecimalFormat("0."+"0".repeat(d),DecimalFormatSymbols.getInstance(Locale.US));return f.format(v).replace('.',',');}
 int minutes(String s){try{String[] a=s.trim().split(":");return Integer.parseInt(a[0])*60+Integer.parseInt(a[1]);}catch(Exception e){return -1;}}
 void calculate(){if(battery==null)return;double cap=num(battery),st=range.getCurrent(),tar=range.getTarget(),kw=num(power),eur=num(price),x=num(xguard);double diff=tar-st;rangeSummary.setText("Cargar desde "+((int)st)+"%  →  "+((int)tar)+"%");chargeAmount.setText("Incremento: "+((int)diff)+"%  ·  "+fmt(cap*diff/100.0,1)+" kWh");if(cap<=0||kw<=0||tar<=st){timeR.setText("00 h 00 min");energyR.setText("0,0 kWh");costR.setText("0,00 €");statusR.setText("");return;}int dm=minutes(departure.getText().toString());if(dm<0){statusR.setText("Selecciona una hora de salida válida.");statusR.setTextColor(Color.rgb(255,107,122));return;}double base=cap*diff/100.0,baseMin=base/kw*60.0,factor=xSwitch.isChecked()?cap*x/(100.0*24.0*kw):0,mins=baseMin/(1.0-factor);if(factor>=1.0||mins>1440){timeR.setText("> 24 h");statusR.setText("⚠ No es posible alcanzar el objetivo en 24 horas con esta configuración.");statusR.setTextColor(Color.rgb(255,107,122));return;}double extra=xSwitch.isChecked()?cap*x/100.0*(mins/1440.0):0,energy=base+extra;timeR.setText(String.format(Locale.US,"%02d h %02d min",(int)(mins/60),(int)Math.round(mins%60)));energyR.setText(fmt(energy,1)+" kWh");costR.setText(fmt(energy*eur,2)+" €");int start=(int)Math.round(dm-mins);start=((start%1440)+1440)%1440;String label="Inicio recomendado  ",tm=String.format(Locale.US,"%02d:%02d",start/60,start%60);android.text.SpannableString ss=new android.text.SpannableString(label+tm);ss.setSpan(new android.text.style.StyleSpan(android.graphics.Typeface.BOLD),label.length(),ss.length(),android.text.Spanned.SPAN_EXCLUSIVE_EXCLUSIVE);statusR.setText(ss);statusR.setTextColor(Color.rgb(0,170,145));}
